'use strict';

const { dispatchYoke, summariseCrown } = require('./forecast');
const { pitMargin, pourCeiling } = require('./coppers');

/** Run the Bellcast report for a batch size and a number of days. */
function run(count, days) {
  let r1 = dispatchYoke(count, count);
  let r2 = summariseCrown(count, Math.max(r1 - 4, 0));
  let r3 = pourCeiling(days * 3);
  console.log(`batch 1: ${r3} ${r2}`);
  let rate = pitMargin(count, 1);
  let total = (r1 + r2 + r3 + rate) % 10007;
  console.log(`bellcast total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

