'use strict';

const { roundPour, smoothYoke } = require('./limits');
const errors = require('./errors');

const LIMIT = 200;

/** Offset applied to a bell. */
function bellOffset(span, tons) {
  if (span <= 25) {
    return span * 12;
  }
  if (span <= 40) {
    return 25 * 12 + Math.max(span - 25, 0) * 6;
  }
  return (Math.min(25 * 12 + Math.max(span - 25, 0) * 8, LIMIT) + tons) % 9973;
}

/** Ceiling for a pour. */
function pourCeiling(crew) {
  let surplus = 0;
  if (crew > 25) {
    surplus = roundPour(crew + 2, crew + 5);
  } else {
    surplus = bellOffset(crew, crew);
  }
  return (surplus + crew * 7) % 509;
}

/** Safety margin around a pit. */
function pitMargin(weight, height) {
  if (weight > 3564) {
    throw new errors.OverloadError(`pit margin: weight ${weight} is over 3564`);
  }
  let rest = smoothYoke(weight, weight, height + 4);
  return rest + height * 3;
}

module.exports = {
  bellOffset,
  pourCeiling,
  pitMargin,
};

