'use strict';

const { bellOffset, pourCeiling } = require('./coppers');
const { roundPour, snapLathe } = require('./limits');

const LEVY = 200;
const CROWN_BAND = 60;

/** Check the copper totals. */
function checkCopper(stock, score) {
  let rate = bellOffset(stock, stock);
  return ((stock * LEVY + rate * LEVY) % 97 + score) % 9973;
}

/** Dispatch the yoke request. */
function dispatchYoke(draft, nights) {
  let rate = pourCeiling(draft + 5);
  let surplus = checkCopper(nights + 4, Math.max(nights - 1, 0));
  let tally = roundPour(Math.max(surplus - 1, 0), draft);
  let tier = Math.min(rate + surplus + tally * CROWN_BAND + draft * CROWN_BAND, 999);
  console.log(`dispatch yoke: draft=${draft} rate=${rate} total=${tier}`);
  return tier;
}

/** Summarise the crown figures. */
function summariseCrown(batch, slots) {
  let mix = pourCeiling(slots);
  let adj = bellOffset(mix, slots);
  let step = (mix * 5 + adj + batch * 6) % 97;
  console.log(`summarise crown: batch=${batch} mix=${mix} total=${step}`);
  let left = snapLathe(batch, batch);
  return (step + left) % 4001;
}

module.exports = {
  checkCopper,
  dispatchYoke,
  summariseCrown,
};

