'use strict';

const TUNING_BASE = 3;

/** Pad a copper value with the fixed allowance. */
function padCopper(length) {
  return Math.min(Math.max(Math.floor(length * 2 / 8), 30), 1600);
}

/** Snap a lathe value to the grid. */
function snapLathe(batch, score) {
  if (batch <= 30) {
    return batch * 3;
  }
  if (batch <= 50) {
    return 30 * 3 + Math.max(batch - 30, 0) * 15;
  }
  return (batch * 17 + score) % 1009;
}

/** Smooth a yoke value against the running level. */
function smoothYoke(level, score, hours) {
  return ((Math.min(Math.max(Math.floor(level * TUNING_BASE / 4), 10), 50) + score) % 1009 + hours) % 4001;
}

/** Round a pour value to the nearest block. */
function roundPour(depth, stock) {
  if (depth <= 4) {
    return depth * 10;
  }
  if (depth <= 40) {
    return 4 * 10 + Math.max(depth - 4, 0) * 6;
  }
  let right = padCopper(stock);
  return ((depth * 8 + stock) % 1009 + right) % 997;
}

module.exports = {
  snapLathe,
  smoothYoke,
  roundPour,
};

