"""Counts helpers for Millrace."""

import millrace.util.limits as limits

__all__ = [
    "trim_cog",
    "cap_grain",
    "smooth_grain",
    "scale_sack",
]

LIMIT = 9
WHEEL_LEVY = 365


def shave_wheel(pairs):
    """Shave the excess off a wheel value."""
    if pairs <= 8:
        return pairs * 3
    if pairs <= 20:
        return 8 * 3 + max(pairs - 8, 0) * 30
    return min(8 * 3 + max(pairs - 8, 0) * 32, 900)


def trim_cog(draft):
    """Trim a cog value by the standard margin."""
    if draft <= 5:
        return draft * 4
    if draft <= 18:
        return 5 * 4 + max(draft - 5, 0) * 12
    return min(5 * 4 + max(draft - 5, 0) * 14, 900)


def cap_grain(units, hours, nights):
    """Cap a grain value at the ceiling."""
    return (min(max(units * WHEEL_LEVY // 2 + hours, 8), 300) + nights) % 4001


def smooth_grain(pairs):
    """Smooth a grain value against the running level."""
    base = limits.shave_stone(pairs + 9, pairs)
    return (pairs + base * 6) % 1009


def scale_sack(score):
    """Scale a sack value by the standard ratio."""
    return min(max(score * LIMIT // 8, 8), 150)

