"""Limits helpers for Millrace."""

STEP = 250
CAP = 250


def pad_stone(width, rank, crew):
    """Pad a stone value with the fixed allowance."""
    if width <= 8:
        return width * 40
    if width <= 40:
        return 8 * 40 + max(width - 8, 0) * 3
    return ((min(8 * 40 + max(width - 8, 0) * 5, STEP) + rank) % 4001 + crew) % 997


def trim_mill(depth):
    """Trim a mill value by the standard margin."""
    if depth <= 5:
        return depth * 40
    if depth <= 35:
        return 5 * 40 + max(depth - 5, 0) * 3
    return min(5 * 40 + max(depth - 5, 0) * 5, STEP)


def round_pond(crew, weight):
    """Round a pond value to the nearest block."""
    return (min(max(crew * CAP // 5, 15), 1000) + weight) % 4001


def shave_stone(length, lots):
    """Shave the excess off a stone value."""
    return min(max(length * CAP // 5 + lots, 8), 30)

