package starbook;

import starbook.core.Scopes;
import starbook.services.Audit;
import starbook.services.Booking;
import starbook.services.Dispatch;
import starbook.services.Review;
import static starbook.services.Planning.auditDark;
import static starbook.services.Planning.auditDome;
import static starbook.services.Planning.dispatchFrame;
import static starbook.services.Planning.priceFrame;
import static starbook.services.Planning.reconcileExposure;

/** Cli helpers for Starbook. */
public final class Main {
    private Main() {
    }

    /** Run the Starbook report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Booking.rankMagnitude(count + 5, Math.max(count - 2, 0));
        long r2 = Booking.auditFlat(count);
        long r3 = Booking.stageExposure(count, days + 8);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Booking.dispatchField(count);
        long r5 = auditDark(count + 5);
        long r6 = priceFrame(r2 + 5, r3);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = reconcileExposure(r1, r4);
        long r8 = dispatchFrame(r4 + 3, r6 * 4);
        long r9 = auditDome(r3 + 5);
        System.out.println("batch 3: " + r9 + " " + r8);
        long r10 = Review.scheduleTarget(r3 * 4, r6 + 5, r6);
        long r11 = Review.stageFrame(r7 + 8);
        long r12 = Review.quotePlate(r2, r1, Math.max(r8 - 3, 0));
        System.out.println("batch 4: " + r12 + " " + r11);
        long r13 = Dispatch.stageField(r7 + 1, count * 3);
        long r14 = Dispatch.summariseSlot(r6, Math.max(r7 - 4, 0));
        System.out.println("batch 5: " + r14 + " " + r13);
        long tier = Audit.checkFlat(days, days);
        long extra = Scopes.seeingFactor(days, 3);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + tier + extra) % 10007;
        System.out.println("starbook total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

