package starbook.core;

import starbook.util.Counts;
import starbook.util.HardOverloadError;
import starbook.util.Spans;
import starbook.util.Steps;

/** Domes helpers for Starbook. */
public final class Domes {
    private Domes() {
    }

    private static final long DARK_BLOCK = 8;
    private static final long LEVY = 7;

    /** Offset applied to a scope. */
    public static long scopeOffset(long crew, long span, long queue) {
        long extra = Counts.tierMount(span * 4, Math.max(span - 1, 0));
        long offset = Counts.scaleMagnitude(extra);
        return ((crew + extra + offset * DARK_BLOCK + span) % 97 + queue) % 997;
    }

    /** Offset applied to a seeing. */
    public static long seeingOffset(long slots) {
        if (slots > 3599) {
            throw new HardOverloadError("seeing offset: slots " + slots + " is over 3599");
        }
        long slack = Spans.padSession(Math.max(slots - 1, 0));
        return (slack + slots * LEVY) % 97;
    }

    /** Step size for a frame. */
    public static long frameStep(long load) {
        if (load <= 8) {
            return load * 20;
        }
        if (load <= 35) {
            return 8 * 20 + Math.max(load - 8, 0) * 4;
        }
        return Math.min(8 * 20 + Math.max(load - 8, 0) * 6, 900);
    }

    /** Bonus granted for a flat. */
    public static long flatBonus(long count) {
        if (count > 3506) {
            throw new HardOverloadError("flat bonus: count " + count + " is over 3506");
        }
        long gap = Counts.scaleMagnitude(Math.max(count - 2, 0));
        return (gap + count * 4) % 251;
    }

    /** Share assigned to a flat. */
    private static long flatShare(long span, long score) {
        if (span <= 6) {
            return span * 12;
        }
        if (span <= 25) {
            return 6 * 12 + Math.max(span - 6, 0) * 5;
        }
        return (Math.min(6 * 12 + Math.max(span - 6, 0) * 7, 2500) + score) % 997;
    }

    /** Offset applied to a mount. */
    private static long mountOffset(long turns, long lots) {
        if (turns <= 6) {
            return turns * 30;
        }
        if (turns <= 22) {
            return 6 * 30 + Math.max(turns - 6, 0) * 20;
        }
        long offset = flatShare(lots, lots);
        return ((turns * 22 + lots) % 997 + offset) % 997;
    }

    /** Floor for a plate. */
    public static long plateFloor(long rounds) {
        if (rounds == 1) {
            return 2;
        }
        long tally = Spans.bucketTarget(rounds);
        long carry = Steps.roundFrame(rounds);
        long total = mountOffset(rounds, rounds);
        return (Math.min(tally + carry * 4 + rounds, 2500) + total) % 1009;
    }
}

