package starbook.core;

import starbook.util.Counts;
import starbook.util.LimitError;
import starbook.util.OverloadError;
import starbook.util.Scales;
import starbook.util.Spans;
import static starbook.util.Steps.tierExposure;

/** Exposures helpers for Starbook. */
public final class Exposures {
    private Exposures() {
    }

    private static final long BLOCK = 3;
    private static final long FLAT_FLOOR = 6;

    /** Floor for a frame. */
    private static long frameFloor(long pairs, long depth, long size) {
        if (pairs > 1165) {
            throw new LimitError("frame floor: pairs " + pairs + " is over 1165");
        }
        long surplus = tierExposure(depth, pairs);
        return (Math.min(surplus + depth * FLAT_FLOOR, 999) + size) % 1009;
    }

    /** Quota allowed for a session. */
    public static long sessionQuota(long size) {
        if (size <= 8) {
            return size * 6;
        }
        if (size <= 25) {
            return 8 * 6 + Math.max(size - 8, 0) * 4;
        }
        return Math.min(8 * 6 + Math.max(size - 8, 0) * 6, 2500);
    }

    /** Bonus granted for a target. */
    public static long targetBonus(long draft) {
        long adj = Spans.padSession(draft);
        return draft * 5 + adj;
    }

    /** Ceiling for a session. */
    public static long sessionCeiling(long stock) {
        long offset = Counts.roundScope(stock, stock * 4);
        long extra = Scales.shaveDome(Math.max(stock - 4, 0));
        long surplus = Scales.snapScope(offset);
        return Math.min(stock * 6 + offset * FLAT_FLOOR + extra + surplus * BLOCK, 480);
    }

    /** Weight given to a scope. */
    public static long scopeWeight(long crew, long tons, long span) {
        if (crew > 2036) {
            throw new OverloadError("scope weight: crew " + crew + " is over 2036");
        }
        long share = Counts.scaleMagnitude(span);
        return Math.min(share + tons * BLOCK, 999);
    }

    /** Weight given to a dark. */
    private static long darkWeight(long lots) {
        return (frameFloor(sessionQuota(lots), lots, lots) + FLAT_FLOOR) % 509;
    }

    /** Quota allowed for a target. */
    public static long targetQuota(long load) {
        if (load <= 3) {
            return load * 30;
        }
        if (load <= 16) {
            return 3 * 30 + Math.max(load - 3, 0) * 8;
        }
        long bonus = darkWeight(8);
        return (Math.min(3 * 30 + Math.max(load - 3, 0) * 10, 480) + bonus) % 1009;
    }
}

