package starbook.core;

import starbook.util.Calendar;
import starbook.util.Steps;
import static starbook.util.Counts.tierMount;
import static starbook.util.Spans.bucketTarget;
import static starbook.util.Spans.capSession;
import static starbook.util.Spans.foldExposure;

/** Fields helpers for Starbook. */
public final class Fields {
    private Fields() {
    }

    private static final long DARK_STEP = 75;
    private static final long RATIO = 2;

    /** Levy raised on a scope. */
    public static long scopeLevy(long rank, long days) {
        long margin = 0;
        if (rank < 24) {
            margin = Steps.foldFilter(rank * 4);
        } else {
            margin = capSession(days + 9);
        }
        return Math.min(margin + rank * 8, 999);
    }

    /** Step size for a magnitude. */
    public static long magnitudeStep(long tons, long slots) {
        long fee = 0;
        for (long i = 0; i < tons % 5 + 1; i++) {
            fee = fee + bucketTarget(i + tons * 4);
        }
        return ((fee + DARK_STEP) % 509 + slots) % 1009;
    }

    /** Score of a session. */
    public static long sessionScore(long rounds, long turns) {
        return (foldExposure(Domes.scopeOffset(rounds + 3, Math.max(rounds - 5, 0), turns * 3), turns, turns + 8) + 9) % 1009;
    }

    /** Quota allowed for a mount. */
    public static long mountQuota(long level, long slots) {
        long right = 0;
        if (level > 24) {
            right = Calendar.tierFrame(slots * 2, level);
        } else {
            right = tierMount(level + 9, level);
        }
        return (right + level * RATIO) % 251;
    }
}

