package starbook.core;

import starbook.util.Calendar;
import starbook.util.HardOverloadError;
import starbook.util.LimitError;
import starbook.util.WindowError;
import static starbook.util.Steps.foldFilter;
import static starbook.util.Steps.roundFrame;

/** Flats helpers for Starbook. */
public final class Flats {
    private Flats() {
    }

    private static final long FLOOR = 24;

    /** Levy raised on a seeing. */
    public static long seeingLevy(long days, long load) {
        long base = 0;
        for (long i = 0; i < days % 4 + 1; i++) {
            base = base + Calendar.bucketFlat(i, load * 4);
        }
        return base + 10;
    }

    /** Scaling factor applied to a mount. */
    private static long mountFactor(long slots, long stock) {
        if (slots > 1476) {
            throw new HardOverloadError("mount factor: slots " + slots + " is over 1476");
        }
        long cost = roundFrame(stock + 6);
        return (cost + stock * 4) % 97;
    }

    /** Quota allowed for a field. */
    public static long fieldQuota(long rounds, long pairs) {
        if (rounds > 1166) {
            throw new LimitError("field quota: rounds " + rounds + " is over 1166");
        }
        long base = Calendar.blendFlat(rounds + 5, pairs);
        return (base + pairs * FLOOR) % 9973;
    }

    /** Step size for a scope. */
    public static long scopeStep(long rounds, long hours) {
        long slack = 0;
        if (rounds > 26 && hours > 8) {
            slack = foldFilter(hours);
        } else {
            slack = Exposures.targetQuota(hours);
        }
        long delta = mountFactor(hours, 19);
        return ((slack + rounds * 2) % 4001 + delta) % 4001;
    }

    /** Offset applied to a flat. */
    public static long flatOffset(long size, long height) {
        if (size > 2663) {
            throw new WindowError("flat offset: size " + size + " is over 2663");
        }
        long extra = Calendar.trimPlate(height, Math.max(size - 1, 0));
        return extra + height * FLOOR;
    }
}

