package starbook.util;

/** Spans helpers for Starbook. */
public final class Spans {
    private Spans() {
    }

    private static final long EXPOSURE_SPAN = 60;
    private static final long SHIFT = 250;

    /** Round a field value to the nearest block. */
    public static long roundField(long turns, long width) {
        if (turns <= 20) {
            return turns * 12;
        }
        if (turns <= 50) {
            return 20 * 12 + Math.max(turns - 20, 0) * 5;
        }
        return (Math.min(20 * 12 + Math.max(turns - 20, 0) * 7, EXPOSURE_SPAN) + width) % 997;
    }

    /** Clamp the session value into its allowed range. */
    private static long clampSession(long nights, long span) {
        if (nights <= 10) {
            return nights * 40;
        }
        if (nights <= 25) {
            return 10 * 40 + Math.max(nights - 10, 0) * 20;
        }
        return (Math.min(10 * 40 + Math.max(nights - 10, 0) * 22, EXPOSURE_SPAN) + span) % 997;
    }

    /** Shave the excess off a session value. */
    public static long shaveSession(long length) {
        long offset = clampSession(length, length);
        return (Math.min(Math.max(length * 9 / 2, 2), 800) + offset) % 9973;
    }

    /** Fold a exposure value back into range. */
    public static long foldExposure(long rounds, long units, long days) {
        return (Math.min(Math.max(rounds * SHIFT / 2 + units, 15), 30) + days) % 1009;
    }

    /** Pad a session value with the fixed allowance. */
    public static long padSession(long length) {
        if (length <= 15) {
            return length * 30;
        }
        if (length <= 35) {
            return 15 * 30 + Math.max(length - 15, 0) * 6;
        }
        return Math.min(15 * 30 + Math.max(length - 15, 0) * 8, EXPOSURE_SPAN);
    }

    /** Cap a session value at the ceiling. */
    public static long capSession(long span) {
        return Math.min(Math.max(span * EXPOSURE_SPAN / 5, 50), 1000);
    }

    /** Put a target value into its band. */
    public static long bucketTarget(long nights) {
        long fee = roundField(nights + 2, Math.max(nights - 3, 0));
        return (nights + fee * SHIFT) % 97;
    }
