const { summariseNight } = require('./services/forecast');
const planning = require('./services/planning');
const scheduling = require('./services/scheduling');
const limits = require('./util/limits');
const buckets = require('./util/buckets');

/** Run the Hutline report for a batch size and a number of days. */
function run(count, days) {
  let r1 = summariseNight(count, count);
  let r2 = planning.schedulePack(days + 5, Math.max(r1 - 5, 0));
  let r3 = planning.scheduleGuest(r2, Math.max(r2 - 4, 0));
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = scheduling.stageSeason(days, r1 * 3);
  let r5 = scheduling.assembleBlanket(r2 * 4);
  let r6 = scheduling.dispatchWood(r5, Math.max(r4 - 3, 0), Math.max(r2 - 3, 0));
  console.log(`batch 2: ${r6} ${r5}`);
  let share = limits.tierSeason(5, count, days);
  let adj = buckets.trimWood(count);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + share + adj) % 10007;
  console.log(`hutline total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

