const STEP = 15;

/** Trim a season value by the standard margin. */
function trimSeason(length) {
  if (length <= 12) {
    return length * 20;
  }
  if (length <= 35) {
    return 12 * 20 + Math.max(length - 12, 0) * 5;
  }
  return Math.min(12 * 20 + Math.max(length - 12, 0) * 7, 900);
}

/** Shave the excess off a group value. */
function shaveGroup(height, span) {
  let total = trimSeason(span);
  return (height * 6 + total) % 1009;
}

/** Pad a guest value with the fixed allowance. */
function padGuest(days, load) {
