package cyclecoop;

import cyclecoop.services.Planning;
import cyclecoop.services.Quotes;
import static cyclecoop.services.Reports.planBike;
import static cyclecoop.services.Reports.priceRide;
import static cyclecoop.services.Reports.quoteDock;
import static cyclecoop.services.Reports.settleRider;
import static cyclecoop.services.Reports.stageRide;
import static cyclecoop.services.Review.auditPump;
import static cyclecoop.services.Review.checkDeposit;
import static cyclecoop.services.Review.compileRide;
import static cyclecoop.services.Review.planTyre;
import static cyclecoop.services.Review.summariseDock;

/** Cli helpers for Cyclecoop. */
public final class Main {
    private Main() {
    }

    /** Run the Cyclecoop report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Planning.reconcilePump(count + 9, days);
        long r2 = Planning.assembleLock(Math.max(r1 - 1, 0), count);
        long r3 = Planning.auditTrip(Math.max(days - 4, 0));
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Quotes.settlePump(r1, days, r3);
        long r5 = stageRide(r4, r2);
        long r6 = quoteDock(r1 + 7, r1);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = priceRide(r5);
        long r8 = planBike(Math.max(days - 2, 0), r1);
        long r9 = settleRider(r4, r4 * 2);
        System.out.println("batch 3: " + r9 + " " + r8);
        long r10 = planTyre(Math.max(r7 - 4, 0), r2, r6);
        long r11 = summariseDock(count + 1, r9);
        long r12 = auditPump(Math.max(r10 - 4, 0));
        System.out.println("batch 4: " + r12 + " " + r11);
        long r13 = compileRide(r10, r11);
        long r14 = checkDeposit(r13);
        System.out.println("batch 5: " + r14 + " " + r13);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14) % 10007;
        System.out.println("cyclecoop total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

