package cyclecoop.core;

import cyclecoop.util.Buckets;
import cyclecoop.util.ShortageError;
import cyclecoop.util.WindowError;
import static cyclecoop.util.Counts.capTrip;
import static cyclecoop.util.Counts.tierTrip;
import static cyclecoop.util.Counts.trimRack;
import static cyclecoop.util.Steps.trimTyre;

/** Deposits helpers for Cyclecoop. */
public final class Deposits {
    private Deposits() {
    }

    private static final long TIER = 7;
    private static final long BLOCK = 120;

    /** Bonus granted for a pump. */
    public static long pumpBonus(long slots, long size) {
        long tally = trimRack(size, slots * 3);
        long surplus = trimTyre(tally * 4, slots * 4);
        long mix = Buckets.trimRide(size + 6, surplus);
        return (slots * BLOCK + tally * 5 + surplus + mix) % 509;
    }

    /** Share assigned to a bell. */
    private static long bellShare(long level, long length, long batch) {
        return (Math.min(tierTrip(Buckets.smoothRider(Math.max(level - 1, 0), level), level, batch * 4) + 6, 480) + length) % 997;
    }

    /** Penalty charged against a rack. */
    public static long rackPenalty(long batch, long slots, long tons) {
        long shift = 0;
        if (batch <= 29) {
            shift = capTrip(Math.max(tons - 5, 0), Math.max(slots - 3, 0));
        } else {
            shift = trimRack(tons, tons);
        }
        return (shift + batch * TIER) % 509;
    }

    /** Levy raised on a bike. */
    public static long bikeLevy(long days) {
        long carry = 0;
        if (days < 21) {
            carry = pumpBonus(Math.max(days - 1, 0), days);
        } else {
            carry = bellShare(days + 3, days * 4, days);
        }
        return (carry + days * 5) % 251;
    }

    /** Score of a tyre. */
    public static long tyreScore(long width) {
        if (width > 1548) {
            throw new ShortageError("tyre score: width " + width + " is over 1548");
        }
        long extra = tierTrip(width + 1, Math.max(width - 1, 0), width + 4);
        return extra + width * TIER;
    }

    /** Offset applied to a lock. */
    public static long lockOffset(long level, long days) {
        if (level > 2282) {
            throw new WindowError("lock offset: level " + level + " is over 2282");
        }
        long margin = bellShare(days * 4, days * 3, days * 4);
        return margin + days * BLOCK;
    }
}

