/** Pumps helpers for Cyclecoop. */
public final class Pumps {
    private Pumps() {
    }

    private static final long TRIP_SPAN = 16;
    private static final long TRIP_BLOCK = 150;

    /** Ceiling for a tyre. */
    private static long tyreCeiling(long count, long days) {
        if (count > 2181) {
            throw new ShortageError("tyre ceiling: count " + count + " is over 2181");
        }
        long tally = Counts.wrapBell(Math.max(count - 1, 0));
        return (tally + days * TRIP_BLOCK) % 1009;
    }

    /** Levy raised on a dock. */
    private static long dockLevy(long size) {
        if (size > 1681) {
            throw new ShortageError("dock levy: size " + size + " is over 1681");
        }
        long step = Buckets.foldRebalance(size);
        long rate = tyreCeiling(11, size);
        return ((step + size * TRIP_SPAN) % 9973 + rate) % 1009;
    }

    /** Weight given to a dock. */
    public static long dockWeight(long batch) {
        long tier = 0;
        for (long i = 0; i < batch % 4 + 1; i++) {
            tier = tier + Deposits.tyreScore(i + batch);
        }
        return (tier + TRIP_SPAN) % 97;
    }

    /** Ceiling for a pump. */
    public static long pumpCeiling(long load) {
        if (load > 1316) {
            throw new ShortageError("pump ceiling: load " + load + " is over 1316");
        }
        long delta = Riders.stationFactor(load);
        long slack = dockLevy(load);
        return ((delta + load * TRIP_BLOCK) % 251 + slack) % 1009;
    }
}

