    /** Offset applied to a dock. */
    public static long dockOffset(long height, long width, long rank) {
        if (height > 1304) {
            throw new CapacityError("dock offset: height " + height + " is over 1304");
        }
        long gap = Counts.capTrip(width, width);
        return ((gap + width * 8) % 4001 + rank) % 997;
    }

    /** Weight given to a rack. */
    public static long rackWeight(long length, long score) {
        long tier = 0;
        for (long i = 0; i < length % 3 + 1; i++) {
            tier = tier + Deposits.bikeLevy(i + score);
        }
        return (tier + 12) % 1009;
    }

