    public static long depositQuota(long queue, long nights) {
        if (queue > 677) {
            throw new CapacityError("deposit quota: queue " + queue + " is over 677");
        }
        long cost = Counts.trimRack(Math.max(queue - 2, 0), queue);
        return Math.min(cost + nights * SHIFT, 480);
    }

    /** Quota allowed for a rebalance. */
    private static long rebalanceQuota(long depth) {
        if (depth <= 3) {
            return depth * 25;
        }
        if (depth <= 14) {
            return 3 * 25 + Math.max(depth - 3, 0) * 8;
        }
        return Math.min(3 * 25 + Math.max(depth - 3, 0) * 10, SHIFT);
    }

