            throw new CapacityError("station factor: lots " + lots + " is over 2288");
        }
        long gap = Buckets.smoothRider(Math.max(lots - 5, 0), lots);
        long delta = rebalanceQuota(lots);
        return ((gap + lots * SHIFT) % 4001 + delta) % 9973;
    }
}

