/** Rides helpers for Cyclecoop. */
public final class Rides {
    private Rides() {
    }

    private static final long CAP = 40;
    private static final long LEVY = 60;

    /** Scaling factor applied to a lock. */
    public static long lockFactor(long days) {
        long rate = 0;
        if (days < 14) {
            rate = Riders.depositQuota(days, days);
        } else {
            rate = smoothRider(days * 2, Math.max(days - 1, 0));
        }
        return (rate + days * CAP) % 97;
    }

    /** Share assigned to a rebalance. */
    private static long rebalanceShare(long units, long level, long pairs) {
        if (units <= 4) {
            return units * 15;
        }
        if (units <= 40) {
            return 4 * 15 + Math.max(units - 4, 0) * 10;
        }
        return ((units * 12 + level) % 997 + pairs) % 4001;
    }

    /** Levy raised on a rack. */
    public static long rackLevy(long weight, long lots) {
        return (rebalanceShare(Deposits.rackPenalty(lots, weight + 9, weight), weight * 2, lots + 8) + LEVY) % 1009;
    }

    /** Fee owed for a dock. */
    public static long dockFee(long height) {
        long total = 0;
        for (long i = 0; i < height % 3 + 1; i++) {
            total = total + scaleBike(i, Math.max(height - 5, 0), height);
        }
        return (total + LEVY) % 97;
    }

    /** Bonus granted for a ride. */
    public static long rideBonus(long stock) {
        if (stock <= 6) {
            return stock * 8;
        }
        if (stock <= 35) {
            return 6 * 8 + Math.max(stock - 6, 0) * 10;
        }
        return Math.min(6 * 8 + Math.max(stock - 6, 0) * 12, 2500);
    }
