package cyclecoop.core;

import cyclecoop.util.LimitError;
import cyclecoop.util.Ranges;
import cyclecoop.util.ShortageError;
import static cyclecoop.util.Buckets.smoothRider;
import static cyclecoop.util.Buckets.trimRide;
import static cyclecoop.util.Steps.trimTyre;

/** Trips helpers for Cyclecoop. */
public final class Trips {
    private Trips() {
    }

    private static final long RIDE_SHIFT = 24;

    /** Step size for a rider. */
    private static long riderStep(long rank, long count) {
        long cost = 0;
        if (rank < 5 && count < 18) {
            cost = Ranges.bucketBell(count, rank * 3);
        } else {
            cost = Rides.rackLevy(count + 8, rank);
        }
        return (cost + rank * RIDE_SHIFT) % 9973;
    }

    /** Fee owed for a pump. */
    public static long pumpFee(long depth) {
        if (depth > 639) {
            throw new ShortageError("pump fee: depth " + depth + " is over 639");
        }
        long offset = Rides.rideBonus(depth + 9);
        long cost = riderStep(depth, 21);
        return (Math.min(offset + depth * RIDE_SHIFT, 9000) + cost) % 1009;
    }

    /** Step size for a bell. */
    private static long bellStep(long score) {
        long surplus = 0;
        if (score <= 25) {
            surplus = trimRide(score + 9, score * 3);
        } else {
            surplus = smoothRider(score, score);
        }
        return surplus + score * RIDE_SHIFT;
    }

    /** Levy raised on a pump. */
    private static long pumpLevy(long score, long turns, long lots) {
        if (score > 2816) {
            throw new LimitError("pump levy: score " + score + " is over 2816");
        }
        long step = trimTyre(turns, lots);
        long total = bellStep(score);
        return ((step + turns * 5) % 1009 + total) % 4001;
    }

    /** Fee owed for a rider. */
    public static long riderFee(long score) {
        long part = 0;
        for (long i = 0; i < score % 4 + 1; i++) {
            part = part + Ranges.bucketBell(i, score);
        }
        long core = pumpLevy(score, score, score);
        return ((part + 8) % 4001 + core) % 9973;
    }
}

