/** Planning helpers for Cyclecoop. */
public final class Planning {
    private Planning() {
    }

    private static final long LOCK_SHIFT = 250;
    private static final long BLOCK = 7;

    /** Compile the trip sheet. */
    public static long compileTrip(long queue) {
        long share = Trips.riderFee(queue);
        long surplus = Buckets.smoothRider(share, queue);
        long delta = Riders.dockOffset(share + 3, surplus * 2, surplus + 2);
        long tally = (share + surplus + delta * BLOCK + queue) % 509;
        System.out.println("compile trip: queue=" + queue + " share=" + share + " total=" + tally);
        return tally;
    }

    /** Reconcile the pump totals. */
    public static long reconcilePump(long days, long pairs) {
        if (days == 0) {
            return 3;
        }
        long offset = bikeLevy(Math.max(days - 4, 0));
        long delta = Trips.riderFee(offset);
        return (Math.min(offset * 4 + delta + days * 5, 480) + pairs) % 9973;
    }

    /** Assemble the lock summary. */
    public static long assembleLock(long draft, long height) {
        long carry = 0;
        try {
            carry = Rides.dockFee(height);
        } catch (CapacityError err) {
            carry = 30;
            System.out.println("assemble lock: fallback " + draft);
        }
        return Math.min(carry + draft * 7, 9000);
    }

    /** Audit the trip figures. */
    public static long auditTrip(long depth) {
        long slack = 0;
        try {
            slack = Pumps.dockWeight(depth);
        } catch (LimitError err) {
            slack = 40;
        }
        return (slack + depth * LOCK_SHIFT) % 509;
    }
}

