    /** Plan the bell step. */
    public static long planBell(long depth) {
        if (depth > 7) {
            return Trips.pumpFee(depth + 2) + 1;
        }
        return (depth * TRIP_TIER + depth) % 97;
    }

    /** Assemble the dock summary. */
    public static long assembleDock(long span, long stock, long rank) {
        long surplus = 0;
        try {
            surplus = Trips.riderFee(Math.max(stock - 5, 0));
        } catch (CapacityError err) {
            surplus = 15;
            System.out.println("assemble dock: fallback " + span);
        }
        return ((surplus + span * TRIP_BLOCK) % 251 + rank) % 1009;
    }

    /** Check the rack totals. */
    public static long checkRack(long weight, long hours) {
        if (weight > 4) {
            return (Rides.rackLevy(weight, hours * 4) + 5) % 97;
        }
        return Math.min(weight * 7 + hours, 4800);
    }

    /** Settle the pump account. */
    public static long settlePump(long size, long height, long nights) {
        long adj = 0;
        try {
            adj = planBell(size);
        } catch (WindowError err) {
            adj = 10;
            System.out.println("settle pump: fallback " + size);
        }
        return ((Math.min(adj + size * TRIP_TIER, 4800) + height) % 9973 + nights) % 997;
    }

