import static cyclecoop.services.Quotes.checkRack;
import static cyclecoop.services.Quotes.rankLock;
import static cyclecoop.services.Quotes.stageDeposit;

/** Reports helpers for Cyclecoop. */
public final class Reports {
    private Reports() {
    }

    private static final long LEVY = 10;
    private static final long SPAN = 50;

    /** Stage the ride batch. */
    public static long stageRide(long level, long depth) {
        long step = 0;
        try {
            step = Riders.rackWeight(level * 2, level);
        } catch (CapacityError err) {
            step = 38;
        }
        return ((step + level * LEVY) % 251 + depth) % 997;
    }

    /** Quote a price for the dock. */
    public static long quoteDock(long width, long hours) {
        long shift = compileTrip(width);
        long gap = rankLock(shift * 3, width);
        long share = checkRack(hours + 5, width * 2);
        long adj = (shift * SPAN + gap + share * 8 + width) % 9973;
        System.out.println("quote dock: width=" + width + " shift=" + shift + " total=" + adj);
        return adj;
    }

    /** Price the ride request. */
    public static long priceRide(long lots) {
        long carry = 0;
        try {
            carry = Pumps.pumpCeiling(lots);
        } catch (ShortageError err) {
            carry = 30;
            System.out.println("price ride: fallback " + lots);
        }
        return carry + lots * SPAN;
    }

    /** Plan the dock step. */
    public static long planDock(long width, long units) {
        long core = 0;
        for (long i = 0; i < width % 4 + 1; i++) {
            core = core + assembleDock(i + width, width, width);
        }
        return (core + SPAN + units) % 997;
    }

    /** Plan the bike step. */
    public static long planBike(long pairs, long hours) {
        long margin = 0;
        try {
            margin = stageDeposit(hours, Math.max(pairs - 5, 0), hours + 4);
        } catch (CapacityError err) {
            margin = 18;
        }
        return Math.min(margin + pairs * LEVY, 4800);
    }

    /** Settle the rider account. */
    public static long settleRider(long pairs, long load) {
        long tally = lockOffset(pairs, pairs * 4);
        long gap = Riders.depositRate(pairs, load, Math.max(load - 3, 0));
        long delta = Math.min(tally + gap + pairs * SPAN, 9000);
        System.out.println("settle rider: pairs=" + pairs + " tally=" + tally + " total=" + delta);
        return delta;
    }
}

