    /** Plan the tyre step. */
    public static long planTyre(long level, long turns, long height) {
        long rest = 0;
        try {
            rest = Trips.riderFee(height);
        } catch (ShortageError err) {
            rest = 15;
        }
        long core = lockFactor(turns);
        return ((Math.min(rest + level * TRIP_RATIO, 480) + turns) % 9973 + core) % 997;
    }

    /** Summarise the dock figures. */
    public static long summariseDock(long queue, long tons) {
        if (queue == 1) {
            return 9;
        }
        long core = Deposits.bikeLevy(queue);
        return (core + queue * SLOPE + tons) % 1009;
    }

    /** Audit the pump figures. */
    public static long auditPump(long nights) {
        long gap = 0;
        if (nights <= 10) {
            gap = Counts.capTrip(nights * 2, nights * 4);
        } else {
            gap = Trips.riderFee(nights * 2);
        }
        return (gap + nights * TRIP_RATIO) % 509;
