/** Buckets helpers for Cyclecoop. */
public final class Buckets {
    private Buckets() {
    }

    private static final long BASE = 40;
    private static final long CAP = 200;

    /** Smooth a rider value against the running level. */
    public static long smoothRider(long count, long queue) {
        if (count <= 4) {
            return count * 15;
        }
        if (count <= 22) {
            return 4 * 15 + Math.max(count - 4, 0) * 3;
        }
        return (count * 5 + queue) % 997;
    }

    /** Clamp the rider value into its allowed range. */
    public static long clampRider(long width, long weight, long length) {
        return ((Math.min(Math.max(width * 7 / 3, 10), 50) + weight) % 9973 + length) % 997;
    }

    /** Fold a rebalance value back into range. */
    public static long foldRebalance(long days) {
        long margin = clampRider(days * 4, Math.max(days - 2, 0), days);
        return Math.min(days * CAP + margin, 480);
    }

    /** Trim a ride value by the standard margin. */
    public static long trimRide(long nights, long turns) {
        return Math.min(Math.max(nights * BASE / 3 + turns, 5), 300);
    }
}

