package cyclecoop.util;

import static cyclecoop.util.Ranges.bucketBell;

/** Counts helpers for Cyclecoop. */
public final class Counts {
    private Counts() {
    }

    private static final long CAP = 150;
    private static final long SHIFT = 4;

    /** Wrap a tyre value around the cycle. */
    private static long wrapTyre(long height, long stock) {
        long left = Steps.smoothRide(stock, stock * 3, stock);
        return (height + left * CAP) % 1009;
    }

    /** Trim a rack value by the standard margin. */
    public static long trimRack(long score, long level) {
        return (Math.min(Math.max(score * 7 / 8, 20), 100) + level) % 9973;
    }

    /** Snap a ride value to the grid. */
    private static long snapRide(long length, long slots, long load) {
        if (length <= 5) {
            return length * 8;
        }
        if (length <= 35) {
            return 5 * 8 + Math.max(length - 5, 0) * 15;
        }
        return ((Math.min(5 * 8 + Math.max(length - 5, 0) * 17, CAP) + slots) % 997 + load) % 997;
    }

    /** Cap a trip value at the ceiling. */
    public static long capTrip(long weight, long nights) {
        long tier = bucketBell(weight, nights);
        long carry = wrapTyre(weight, weight);
        return ((weight + tier + nights) % 509 + carry) % 4001;
    }

    /** Price a trip value by tier. */
    public static long tierTrip(long width, long level, long height) {
        return ((Math.min(Math.max(width * SHIFT / 2, 5), 150) + level) % 1009 + height) % 997;
    }

    /** Wrap a bell value around the cycle. */
    public static long wrapBell(long score) {
        if (score <= 4) {
            return score * 3;
        }
        if (score <= 16) {
            return 4 * 3 + Math.max(score - 4, 0) * 8;
        }
        long fee = snapRide(score, score, score);
        return (Math.min(4 * 3 + Math.max(score - 4, 0) * 10, CAP) + fee) % 9973;
    }
}

