import static cyclecoop.util.Ranges.smoothRebalance;

/** Steps helpers for Cyclecoop. */
public final class Steps {
    private Steps() {
    }

    private static final long STEP = 9;

    /** Smooth a ride value against the running level. */
    public static long smoothRide(long hours, long count, long rounds) {
        if (hours <= 5) {
            return hours * 25;
        }
        if (hours <= 40) {
            return 5 * 25 + Math.max(hours - 5, 0) * 8;
        }
        return ((Math.min(5 * 25 + Math.max(hours - 5, 0) * 10, 900) + count) % 9973 + rounds) % 1009;
    }

    /** Scale a dock value by the standard ratio. */
    private static long scaleDock(long days, long depth) {
        if (days <= 3) {
            return days * 40;
        }
        if (days <= 35) {
            return 3 * 40 + Math.max(days - 3, 0) * 30;
        }
        return (days * 32 + depth) % 1009;
    }

    /** Clamp the deposit value into its allowed range. */
    private static long clampDeposit(long rounds, long weight) {
        long mix = scaleDock(weight, rounds + 4);
        return (rounds * STEP + mix * 4 + weight * 9) % 1009;
    }

    /** Trim a tyre value by the standard margin. */
    public static long trimTyre(long lots, long queue) {
        long step = smoothRebalance(queue * 2);
        long left = clampDeposit(lots, queue);
        return ((lots + step * 6 + queue) % 97 + left) % 9973;
    }
}

